def clusters(A):
    H,W=A.shape; seen=np.zeros((H,W),bool); res=[]
    for i in range(H):
        for j in range(W):
            if A[i][j]!=0 and not seen[i,j]:
                st=[(i,j)]; comp=[]; seen[i,j]=True
                while st:
                    a,b=st.pop(); comp.append((a,b))
