    return G
G=load()
def clusters(A):
    H,W=A.shape; seen=np.zeros((H,W),bool); out=[]
    for i in range(H):
        for j in range(W):
            if A[i,j]!=0 and not seen[i,j]:
                st=[(i,j)]; comp=[]; seen[i,j]=True
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and A[x,y]!=0 and not seen[x,y]:
                            seen[x,y]=True; st.append((x,y))
                out.append(comp)
    return sorted(out,key=len,reverse=True)
def solve(A):
    C=clusters(np.array(A)); B=sorted(C,key=lambda c:-len(c)); big=B[0]; small=B[1]
    r1=min(p[0] for p in big); c1=min(p[1] for p in big)
    r2=min(p[0] for p in small); c2=min(p[1] for p in small)
    h1=max(p[0] for p in big)-r1+1; w1=max(p[1] for p in big)-c1+1
    h2=max(p[0] for p in small)-r2+1; w2=max(p[1] for p in small)-c2+1
    R1=np.zeros((h1,w1),dtype=int); R2=np.zeros((h2,w2),dtype=int)
    for r,c in big: R1[r-r1,c-c1]=A[r][c]
    for r,c in small: R2[r-r2,c-c2]=A[r][c]
    D=np.zeros(R1.shape,bool)
    for i in range(h2):
        for j in range(w2):
            ni,nj=i+(r2-r1),j+(c2-c1)
            if 0<=ni<h1 and 0<=nj<w1 and R1[ni,nj]!=0 and R2[i,j]!=0 and R1[ni,nj]!=R2[i,j]:
                D[ni,nj]=True
    ys,xs=np.where(D)
    if len(ys)==0: return [[0]]
    top,left=ys.min(),xs.min()
    return [[8 if D[top+i][left+j] else 0 for j in range(xs.max()-xs.min()+1)] for i in range(ys.max()-ys.min()+1)]
